mapper.select:
SELECT c.id, c.title, c.instructor, c.department, COALESCE(total_versions.total_version_count, 0) AS totalVersionCount, CASE WHEN #{request.keyword} IS NOT NULL AND #{request.keyword} != '' AND LOWER(CONCAT(c.title, ' ', c.instructor, ' ', c.department)) LIKE CONCAT('%', LOWER(#{request.keyword}), '%') THEN COALESCE(total_versions.total_version_count, 0) ELSE COALESCE(filtered_versions.matched_version_count, 0) END AS matchedVersionCount, COALESCE(filtered_versions.latest_matched_version_updated_at, c.updated_at) AS latestMatchedVersionUpdatedAt FROM outline_course c LEFT JOIN ( SELECT ov.course_id, COUNT(*) AS total_version_count FROM outline_version ov WHERE ov.deleted = 0 GROUP BY ov.course_id ) total_versions ON total_versions.course_id = c.id LEFT JOIN ( SELECT ov.course_id, COUNT(*) AS matched_version_count, MAX(ov.updated_at) AS latest_matched_version_updated_at FROM outline_version ov WHERE ov.deleted = 0
AND ov.semester = #{request.semester}
AND ov.status = #{request.versionStatus}
AND ov.completion_state = #{request.completionState}
AND ov.archive_state = #{request.archiveState}
AND LOWER(CONCAT(ov.version_name, ' ', ov.note, ' ', ov.updated_by)) LIKE CONCAT('%', LOWER(#{request.keyword}), '%')
GROUP BY ov.course_id ) filtered_versions ON filtered_versions.course_id = c.id WHERE c.deleted = 0
AND (filtered_versions.course_id IS NOT NULL OR COALESCE(total_versions.total_version_count, 0) = 0)
AND ( #{request.keyword} IS NULL OR #{request.keyword} = '' OR LOWER(CONCAT(c.title, ' ', c.instructor, ' ', c.department)) LIKE CONCAT('%', LOWER(#{request.keyword}), '%') OR filtered_versions.course_id IS NOT NULL OR COALESCE(total_versions.total_version_count, 0) = 0 )
ORDER BY latestMatchedVersionUpdatedAt DESC, c.updated_at DESC, c.id DESC
